using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;
public static class AuditHangarApproaches {
 public static string Main(){var root=GameObject.Find("New_Map").transform;var terrain=root.GetComponentInChildren<Terrain>();var result=new List<string>();foreach(var h in root.Find("11_Five_Hangar_Farm").Cast<Transform>().Where(t=>t.name.StartsWith("Hangar "))){var start=new Vector3(0,0,32);var end=h.TransformPoint(new Vector3(0,0,18));var bad=new HashSet<string>();for(int i=0;i<=50;i++){var p=h.name.StartsWith("Hangar 3")?(i<=25?Vector3.Lerp(start,new Vector3(-18,0,28),i/25f):Vector3.Lerp(new Vector3(-18,0,28),end,(i-25)/25f)):Vector3.Lerp(start,end,i/50f);p.y=terrain.SampleHeight(p)+terrain.transform.position.y+1.15f;foreach(var c in Physics.OverlapBox(p,new Vector3(.6f,.65f,.6f),Quaternion.identity,~0,QueryTriggerInteraction.Ignore)){if(c is TerrainCollider||c.GetComponentInParent<PlayerController>()||!c.transform.IsChildOf(root))continue;bad.Add(c.name+" parent="+c.transform.parent.name);}}result.Add(h.name+" approach obstacles="+bad.Count+" "+string.Join(";",bad));}string r=string.Join("\n",result);File.WriteAllText("output/NewMap/FiveHangars/approaches.txt",r);return r;}
}

